begin;
create table public.reliable_study_protocols (id text,version integer,stage text,document jsonb,sha256 text,locked_at timestamptz,primary key(id),check(version>0));
create table public.reliable_study_campaigns (id text,protocol_id text,title text,stage text,status text,planned_runs integer,recorded_runs integer,experiment_type text,elapsed_seconds numeric,limitations jsonb,provenance jsonb,usage jsonb,primary key(id),foreign key(protocol_id) references reliable_study_protocols(id),check(status in ('complete','failed','partial','excluded','invalid')),check(recorded_runs between 0 and planned_runs));
create table public.reliable_study_configurations (id text,campaign_id text,algorithm text,skewness numeric,budget_bytes integer,budget_regime text,input_sha256 text,details jsonb,requested_resources jsonb,actual_resources jsonb,primary key(id),unique(campaign_id,id),foreign key(campaign_id) references reliable_study_campaigns(id),check(budget_bytes>0));
create table public.reliable_study_runs (id text,campaign_id text,configuration_id text,protocol_id text,stage text,status text,reason text,algorithm text,seed integer,input_sha256 text,raw_sha256 text,analysis_sha256 text,analysis_version text,started_at timestamptz,ended_at timestamptz,measurements jsonb,primary key(id),foreign key(campaign_id,configuration_id) references reliable_study_configurations(campaign_id,id),foreign key(protocol_id) references reliable_study_protocols(id),check(status in ('complete','failed','partial','excluded','invalid')),check(status='complete' or reason is not null));
create table public.reliable_study_measurements (run_id text,metric text,value numeric,status text,reason text,units text,primary key(run_id,metric),foreign key(run_id) references reliable_study_runs(id),check(status in ('recorded','missing','invalid','ambiguous','excluded')),check((status='recorded' and value is not null) or (status<>'recorded' and value is null and reason is not null)));
create table public.reliable_study_summaries (configuration_id text,campaign_id text,planned integer,recorded integer,failed integer,excluded integer,statistics jsonb,interval_kind text,observed_keys integer,query_population text,zero_outlier_runs integer,lossless_runs integer,interval_valid_runs integer,primary key(configuration_id),foreign key(campaign_id,configuration_id) references reliable_study_configurations(campaign_id,id),check(recorded+failed+excluded=planned));
create table public.reliable_study_sources (reference_number integer,citation text,doi text,kind text,role text,source_url text,retrieved_url text,access_status text,review_status text,retrieved_version text,sha256 text,byte_count bigint,pages integer,findings text,limitations text,retrieval_attempts jsonb,reviewer jsonb,primary key(reference_number),check(reference_number between 0 and 46),check(review_status in ('complete','partial','unreviewed','unavailable')));
create table public.reliable_study_claims (id text,location text,description text,assessment text,evidence text,limitation text,proposed_check text,required_inputs text,feasibility text,primary key(id),check(assessment in ('reproduced','discrepant','inconclusive','untested')));
create table public.reliable_study_published (id text,source_number integer,location text,metric text,values jsonb,units text,primary key(id),foreign key(source_number) references reliable_study_sources(reference_number));
create table public.reliable_study_controls (id text,protocol_id text,stage text,payload jsonb,primary key(id),foreign key(protocol_id) references reliable_study_protocols(id));
create table public.reliable_study_control_runs (id text,control_id text,implementation text,seed integer,key integer,weight integer,status text,reason text,raw_sha256 text,payload jsonb,primary key(id),foreign key(control_id) references reliable_study_controls(id),check(status in ('complete','failed','excluded','invalid')),check(status='complete' or reason is not null));
create table public.reliable_study_meta (id text,analysis_version text,assessment_sha256 text,review_definition text,label_definitions jsonb,validation jsonb,counts jsonb,provenance jsonb,costs jsonb,primary key(id));
create table public.reliable_study_artifacts (id text,sha256 text,byte_count bigint,manifest jsonb,storage_path text,payload jsonb,primary key(id),check(byte_count>=0));
create index reliable_measurement_run on reliable_study_measurements(run_id);
create index reliable_runs_configuration on reliable_study_runs(configuration_id,seed);
alter table public.reliable_study_protocols enable row level security;
revoke all on public.reliable_study_protocols from anon,authenticated;
grant all on public.reliable_study_protocols to service_role;
grant select on public.reliable_study_protocols to anon,authenticated;
create policy reliable_public_read on public.reliable_study_protocols for select to anon,authenticated using(true);
drop policy if exists jumpserve_require_signed_in_user on public.reliable_study_protocols;
create policy reliable_deny_browser_writes on public.reliable_study_protocols as restrictive for all to anon,authenticated using(true) with check(false);
alter table public.reliable_study_campaigns enable row level security;
revoke all on public.reliable_study_campaigns from anon,authenticated;
grant all on public.reliable_study_campaigns to service_role;
grant select on public.reliable_study_campaigns to anon,authenticated;
create policy reliable_public_read on public.reliable_study_campaigns for select to anon,authenticated using(true);
