revoke all on public.reliable_study_control_runs from anon,authenticated;
grant all on public.reliable_study_control_runs to service_role;
grant select on public.reliable_study_control_runs to anon,authenticated;
create policy reliable_public_read on public.reliable_study_control_runs for select to anon,authenticated using(true);
