alter table public.reliable_study_artifacts enable row level security;
revoke all on public.reliable_study_artifacts from anon,authenticated;
grant all on public.reliable_study_artifacts to service_role;
alter table public.agent_prompt_versions drop constraint agent_prompt_versions_module_id_check;
alter table public.agent_prompt_versions add constraint agent_prompt_versions_module_id_check check(module_id in ('congestion-control-emulated','congestion-control-real-world','leo-emergency-failover','http2-compliance-study','reliable-sketch-study'));
alter table public.agent_prompt_settings drop constraint agent_prompt_settings_module_id_check;
alter table public.agent_prompt_settings add constraint agent_prompt_settings_module_id_check check(module_id in ('congestion-control-emulated','congestion-control-real-world','leo-emergency-failover','http2-compliance-study','reliable-sketch-study'));
alter table public.agent_sessions drop constraint agent_sessions_module_id_check;
alter table public.agent_sessions add constraint agent_sessions_module_id_check check(module_id in ('congestion-control-emulated','congestion-control-real-world','leo-emergency-failover','http2-compliance-study','reliable-sketch-study'));
insert into agent_prompt_settings(module_id) values('reliable-sketch-study') on conflict(module_id) do nothing;
insert into storage.buckets(id,name,public) values('reliable-study-raw','reliable-study-raw',false) on conflict(id) do nothing;
create policy reliable_private_raw on storage.objects as restrictive for all to anon,authenticated using(bucket_id<>'reliable-study-raw') with check(bucket_id<>'reliable-study-raw');
notify pgrst,'reload schema';
commit;
